create table wksp_dtesc.sgt_tipo_interfaz (
    id          number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    nombre      varchar2(64 char) not null enable,
    descripcion varchar2(1000 char)
);

alter table wksp_dtesc.sgt_tipo_interfaz add primary key ( id )
    using index enable;


